/**
 * Crate Yard — a tiny toy: a yard of crates, barrels and a lamp loaded from .glb files. Tap a crate to make it hop.
 *
 * Sample for KUMODeck Game Studio, written to exercise:
 *   - models loaded with GLTFLoader (assets/*.glb, generated by tools/make-assets.mjs) and cloned
 *   - the author's marks: the crates carry `userData.studioKey` ("crate-1" …), the lamp `userData.studioAsset`
 *   - an unnamed loaded model (the second barrel copy has its name cleared → listed as "no name")
 *   - an external texture loaded with TextureLoader (assets/grass.png on the ground)
 *   - studio.waitForReady() / studio.ready(): the layout is only final after the models arrive, so the editor is
 *     told when to stop the game (both calls are optional and do nothing outside the editor)
 */

import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { applyPlacement } from './studio-placement.js';

window.studio?.waitForReady?.();

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(devicePixelRatio || 1, 2));
renderer.shadowMap.enabled = true;
document.body.prepend(renderer.domElement);
const scene = new THREE.Scene();
scene.background = new THREE.Color(0xcfe8ff);
const camera = new THREE.PerspectiveCamera(50, 1, 0.1, 200);
camera.position.set(9, 9, 12);
camera.lookAt(0, 0, 0);

scene.add(new THREE.HemisphereLight(0xffffff, 0x88aa77, 1.5));
const sun = new THREE.DirectionalLight(0xffffff, 2.2);
sun.position.set(6, 14, 8);
sun.castShadow = true;
sun.shadow.camera.left = sun.shadow.camera.bottom = -12;
sun.shadow.camera.right = sun.shadow.camera.top = 12;
scene.add(sun);

const grass = new THREE.TextureLoader().load('assets/grass.png');
grass.wrapS = grass.wrapT = THREE.RepeatWrapping;
grass.repeat.set(8, 8);
grass.colorSpace = THREE.SRGBColorSpace;
const ground = new THREE.Mesh(new THREE.PlaneGeometry(24, 24), new THREE.MeshStandardMaterial({ map: grass, roughness: 1 }));
ground.name = 'ground';
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

const loader = new GLTFLoader();
const [crate, barrel, lamp] = await Promise.all(['assets/crate.glb', 'assets/barrel.glb', 'assets/lamp.glb'].map((u) => loader.loadAsync(u)));
const shadows = (o) => o.traverse((m) => m.isMesh && ((m.castShadow = true), (m.receiveShadow = true)));

const crates = [];
[[-3, 0, -1], [-1.8, 0, -1.2], [-2.4, 1, -1.1], [2, 0, 2]].forEach(([x, y, z], i) => {
  const c = crate.scene.clone();
  c.userData.studioKey = `crate-${i + 1}`;
  c.position.set(x, y, z);
  c.rotation.y = i * 0.3;
  shadows(c);
  scene.add(c);
  crates.push(c);
});

const barrel1 = barrel.scene.clone();
barrel1.name = 'barrel';
barrel1.position.set(3, 0, -3);
shadows(barrel1);
scene.add(barrel1);
const barrel2 = barrel.scene.clone();
barrel2.name = ''; // deliberately anonymous: it gets a path key and is shown as "no name"
barrel2.traverse((o) => (o.name = ''));
barrel2.position.set(4, 0, -2);
shadows(barrel2);
scene.add(barrel2);

lamp.scene.name = 'lamp';
lamp.scene.userData.studioAsset = 'assets/lamp.glb';
lamp.scene.position.set(0, 0, -5);
shadows(lamp.scene);
scene.add(lamp.scene);

await applyPlacement(scene, './placement.json');
// The camera is passed because the game has not rendered yet (the loop starts below).
window.studio?.ready?.({ camera });

function resize() {
  renderer.setSize(innerWidth, innerHeight);
  camera.aspect = innerWidth / innerHeight;
  camera.fov = camera.aspect < 1 ? 70 : 50;
  camera.updateProjectionMatrix();
}
addEventListener('resize', resize);
resize();

// ------------------------------------------------------------------ tap a crate → hop
const ray = new THREE.Raycaster();
const hopping = new Map(); // crate → { t, baseY }
let hops = 0;
renderer.domElement.addEventListener('pointerdown', (e) => {
  ray.setFromCamera(new THREE.Vector2((e.clientX / innerWidth) * 2 - 1, -(e.clientY / innerHeight) * 2 + 1), camera);
  const hit = ray.intersectObjects(crates, true)[0];
  if (!hit) return;
  let c = hit.object;
  while (!crates.includes(c)) c = c.parent;
  if (!hopping.has(c)) hopping.set(c, { t: 0, baseY: c.position.y });
  document.getElementById('hops').textContent = ++hops;
});

const clock = new THREE.Clock();
renderer.setAnimationLoop(() => {
  const dt = Math.min(clock.getDelta(), 0.05);
  for (const [c, h] of hopping) {
    h.t += dt;
    c.position.y = h.baseY + Math.max(0, Math.sin(h.t * Math.PI * 2)) * 1.2;
    if (h.t >= 0.5) (c.position.y = h.baseY), hopping.delete(c);
  }
  renderer.render(scene, camera);
});
